const phoneExists = `-- name: PhoneExists :one
SELECT EXISTS (
    SELECT 1 FROM users
    WHERE phone = $1
      AND deleted_at IS NULL
      AND ($2::bigint IS NULL OR id <> $2::bigint)
)
`

type PhoneExistsParams struct {
	Phone     *string `json:"phone"`
	ExcludeID int64   `json:"exclude_id"`
}

func (q *Queries) PhoneExists(ctx context.Context, arg PhoneExistsParams) (bool, error) {
	row := q.db.QueryRow(ctx, phoneExists, arg.Phone, arg.ExcludeID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}

