const updateUser = `-- name: UpdateUser :one
UPDATE users
SET first_name  = $1,
    last_name   = $2,
    name        = $3,
    phone       = $4,
    is_active   = $5,
    branch_id   = $6,
    updated_by  = $7,
    updated_at  = now()
WHERE id = $8 AND deleted_at IS NULL
  AND ($9::boolean OR tenant_id = $10::bigint)
  -- Optional optimistic lock: when the client sends the updated_at it last
  -- saw, a concurrent change makes this match nothing (409 in the service).
  AND ($11::timestamptz IS NULL
       OR updated_at = $11::timestamptz)
RETURNING id, tenant_id, branch_id, active_branch_id, first_name, last_name, user_name, name, email, email_verified_at, phone, phone_verified_at, password, is_active, last_login_at, last_active_device, remember_token, created_by, updated_by, created_at, updated_at, deleted_at, invited_at, invited_by, invitation_accepted_at, erased_at
`

type UpdateUserParams struct {
	FirstName         *string            `json:"first_name"`
	LastName          *string            `json:"last_name"`
	Name              string             `json:"name"`
	Phone             *string            `json:"phone"`
	IsActive          int16              `json:"is_active"`
	BranchID          *int64             `json:"branch_id"`
	UpdatedBy         *int64             `json:"updated_by"`
	ID                int64              `json:"id"`
	AllTenants        bool               `json:"all_tenants"`
	TenantID          int64              `json:"tenant_id"`
	ExpectedUpdatedAt pgtype.Timestamptz `json:"expected_updated_at"`
}

func (q *Queries) UpdateUser(ctx context.Context, arg UpdateUserParams) (User, error) {
	row := q.db.QueryRow(ctx, updateUser,
		arg.FirstName,
		arg.LastName,
		arg.Name,
		arg.Phone,
		arg.IsActive,
		arg.BranchID,
		arg.UpdatedBy,
		arg.ID,
		arg.AllTenants,
		arg.TenantID,
		arg.ExpectedUpdatedAt,
	)
	var i User
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.BranchID,
		&i.ActiveBranchID,
		&i.FirstName,
		&i.LastName,
		&i.UserName,
		&i.Name,
		&i.Email,
		&i.EmailVerifiedAt,
		&i.Phone,
		&i.PhoneVerifiedAt,
		&i.Password,
		&i.IsActive,
		&i.LastLoginAt,
		&i.LastActiveDevice,
		&i.RememberToken,
		&i.CreatedBy,
		&i.UpdatedBy,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.InvitedAt,
		&i.InvitedBy,
		&i.InvitationAcceptedAt,
		&i.ErasedAt,
	)
	return i, err
}

